// tb/v3/tb_ch08_norm.v
// Cycle-accurate, bit-exact testbench for rtl/v3/ch08_norm_score.v
// Compatible with iverilog -g2012 -Wall
//
// Verification protocol:
// - Reads cycle vectors generated by Python twin (verify_v3/ch08_twin.py)
// - Covers Clean Speech Frames, Noisy Frame (SNR 5 dB), Stress Frame Full-Scale (R0 ~ 2^42),
//   Small Amplitude Frame (sh = 0), Silence Frame (R0 = 0), and pipeline bubbles/stalls
// - 2-phase sampling convention:
//     * Inputs driven at @(negedge clk)
//     * Registered outputs checked at @(posedge clk); #1
// - Does not abort on mismatch; counts all comparison errors and reports total
// - Strict loop condition (no break/continue/return for iverilog 12 compatibility)

`timescale 1ns/1ps

module tb_ch08_norm;

    localparam integer IN_W            = 48;
    localparam integer RN_W            = 27;
    localparam integer R0N_W           = 26;
    localparam integer OUT_W           = 28;
    localparam integer TAU_SCAN_MIN    = 26;
    localparam integer TAU_SCAN_MAX    = 214;
    localparam integer EXPECTED_CYCLES = 1214;

    // Clock generation (50 MHz, 20 ns period)
    reg clk = 0;
    always #10 clk = ~clk;

    // DUT signals
    reg                     rst_n;
    reg                     in_valid;
    reg  [7:0]              in_tau;
    reg  signed [IN_W-1:0]  in_R;

    wire                    out_valid;
    wire [7:0]              out_tau;
    wire signed [OUT_W-1:0] out_U;
    wire signed [OUT_W-1:0] out_Sc;
    wire [R0N_W-1:0]        out_R0n;
    wire [4:0]              out_sh;
    wire                    out_last;

    // Instantiate DUT
    ch08_norm_score #(
        .IN_W         (IN_W),
        .RN_W         (RN_W),
        .R0N_W        (R0N_W),
        .OUT_W        (OUT_W),
        .TAU_SCAN_MIN (TAU_SCAN_MIN),
        .TAU_SCAN_MAX (TAU_SCAN_MAX),
        .INIT_FILE    ("golden_v2/rom/ck_rom.hex")
    ) dut (
        .clk       (clk),
        .rst_n     (rst_n),
        .in_valid  (in_valid),
        .in_tau    (in_tau),
        .in_R      (in_R),
        .out_valid (out_valid),
        .out_tau   (out_tau),
        .out_U     (out_U),
        .out_Sc    (out_Sc),
        .out_R0n   (out_R0n),
        .out_sh    (out_sh),
        .out_last  (out_last)
    );

    // Testbench tracking variables
    integer stim_fd;
    integer exp_fd;
    integer cycle_idx;
    integer errors;

    // Stimulus record variables
    integer stim_rst_n;
    integer stim_in_vld;
    integer stim_in_tau;
    reg signed [63:0] stim_in_R;

    // Expected record variables
    integer exp_out_vld;
    integer exp_out_tau;
    reg signed [63:0] exp_out_U;
    reg signed [63:0] exp_out_Sc;
    integer exp_out_R0n;
    integer exp_out_sh;
    integer exp_out_last;

    initial begin
        rst_n     = 0;
        in_valid  = 0;
        in_tau    = 8'd0;
        in_R      = {IN_W{1'b0}};
        cycle_idx = 0;
        errors    = 0;

        // Open stimulus file (try verify_v3 path then relative path)
        stim_fd = $fopen("verify_v3/tb_ch08_norm_stim.txt", "r");
        if (stim_fd == 0) stim_fd = $fopen("tb_ch08_norm_stim.txt", "r");
        if (stim_fd == 0) begin
            $display("[FAIL] Cannot open tb_ch08_norm_stim.txt");
            $finish;
        end

        // Open expected file (try verify_v3 path then relative path)
        exp_fd = $fopen("verify_v3/tb_ch08_norm_expected.txt", "r");
        if (exp_fd == 0) exp_fd = $fopen("tb_ch08_norm_expected.txt", "r");
        if (exp_fd == 0) begin
            $display("[FAIL] Cannot open tb_ch08_norm_expected.txt");
            $finish;
        end

        $display("=== STARTING CH08 NORMALIZATION & SCORING VERIFICATION ===");

        // Align to falling edge
        @(negedge clk);

        while ($fscanf(stim_fd, "%d %d %d %d\n",
                       stim_rst_n, stim_in_vld, stim_in_tau, stim_in_R) == 4 &&
               $fscanf(exp_fd, "%d %d %d %d %d %d %d\n",
                       exp_out_vld, exp_out_tau, exp_out_U, exp_out_Sc,
                       exp_out_R0n, exp_out_sh, exp_out_last) == 7) begin

            // 1. Drive inputs during clock low phase
            rst_n    = (stim_rst_n != 0) ? 1'b1 : 1'b0;
            in_valid = (stim_in_vld != 0) ? 1'b1 : 1'b0;
            in_tau   = stim_in_tau[7:0];
            in_R     = stim_in_R[IN_W-1:0];

            // 2. Wait for clock rising edge and sample registered outputs after #1
            @(posedge clk);
            #1;

            // Check out_valid
            if (out_valid !== ((exp_out_vld != 0) ? 1'b1 : 1'b0)) begin
                $display("[FAIL] Cycle %0d: out_valid mismatch DUT=%b EXP=%b",
                         cycle_idx, out_valid, exp_out_vld != 0);
                errors = errors + 1;
            end

            // Check outputs when out_valid is active
            if (out_valid) begin
                if (out_tau !== exp_out_tau[7:0]) begin
                    $display("[FAIL] Cycle %0d: out_tau mismatch DUT=%0d EXP=%0d",
                             cycle_idx, out_tau, exp_out_tau);
                    errors = errors + 1;
                end

                if (out_U !== exp_out_U[OUT_W-1:0]) begin
                    $display("[FAIL] Cycle %0d: out_U mismatch DUT=%0d EXP=%0d",
                             cycle_idx, $signed(out_U), $signed(exp_out_U));
                    errors = errors + 1;
                end

                if (out_Sc !== exp_out_Sc[OUT_W-1:0]) begin
                    $display("[FAIL] Cycle %0d: out_Sc mismatch DUT=%0d EXP=%0d",
                             cycle_idx, $signed(out_Sc), $signed(exp_out_Sc));
                    errors = errors + 1;
                end

                if (out_R0n !== exp_out_R0n[R0N_W-1:0]) begin
                    $display("[FAIL] Cycle %0d: out_R0n mismatch DUT=%0d EXP=%0d",
                             cycle_idx, out_R0n, exp_out_R0n);
                    errors = errors + 1;
                end

                if (out_sh !== exp_out_sh[4:0]) begin
                    $display("[FAIL] Cycle %0d: out_sh mismatch DUT=%0d EXP=%0d",
                             cycle_idx, out_sh, exp_out_sh);
                    errors = errors + 1;
                end

                if (out_last !== ((exp_out_last != 0) ? 1'b1 : 1'b0)) begin
                    $display("[FAIL] Cycle %0d: out_last mismatch DUT=%b EXP=%b",
                             cycle_idx, out_last, exp_out_last != 0);
                    errors = errors + 1;
                end
            end

            cycle_idx = cycle_idx + 1;
            @(negedge clk);
        end

        $fclose(stim_fd);
        $fclose(exp_fd);

        $display("-------------------------------------------------------");
        $display("Simulation finished. Total cycles tested: %0d", cycle_idx);

        if (cycle_idx != EXPECTED_CYCLES) begin
            $display("[FAIL] Total cycles read (%0d) does not match EXPECTED_CYCLES (%0d)!",
                     cycle_idx, EXPECTED_CYCLES);
            errors = errors + 1;
        end

        $display("Total comparison errors: %0d", errors);

        if (errors == 0) begin
            $display("=== ALL %0d VECTORS MATCHED SUCCESSFULLY ===", cycle_idx);
        end else begin
            $display("[FAIL] Verification finished with %0d errors!", errors);
        end
        $display("-------------------------------------------------------");
        $finish;
    end

endmodule
